CREATE TABLE q(test,expr); INSERT INTO q VALUES('1','one AND five'),('2','one NEAR five'),('3','one NEAR/1 five'),('4','one NEAR/2 five'),('5','one NEAR/3 five'),('6','on* AND fi*'),('7','on* NEAR fi*'),('8','on* NEAR/1 fi*'),('9','on* NEAR/2 fi*'),('10','on* NEAR/3 fi*'); CREATE TABLE result AS SELECT test,'ASC' AS direction,(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid ASC)) AS docs FROM q UNION ALL SELECT test,'DESC',(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid DESC)) FROM q;